#!/bin/bash
# Codex PreToolUse hook — generated by scripts/gen-harness-codex.ts, do not edit.
# Rejects (exit 2, reason on stderr) a shell command that prints more than one
# Markdown file: output past ~10k tokens loses its middle, and a skill read inside
# a multi-file batch loses its output contract. Single-file reads, sed ranges,
# listings and searches pass; anything unparseable passes.

INPUT=$(cat)
command -v python3 >/dev/null 2>&1 || exit 0
TEA_RAGS_HOOK_INPUT="$INPUT" exec python3 -I - <<'PY'
import ast, json, os, re, shlex, sys

READERS = {"cat", "head", "tail", "less", "more", "bat", "batcat", "nl", "tac", "awk", "sed"}
INTERPRETERS = {"python", "python3", "node", "ruby", "perl", "deno", "bun"}
SHELLS = {"bash", "sh", "zsh", "dash"}
PREFIXES = {"sudo", "command", "env", "time", "nohup", "exec", "xargs", "do", "then", "else", "{", "(", "!"}
SEPARATORS = {"&&", "||", ";", "|", "&", "\n", "(", ")", ";;", "|&"}
READ_CALL = re.compile(r"read_text|read_bytes|\.read\(|open\(|readFileSync|readFile\(|File\.read|readlines|\bcat\b")
MD_LITERAL = re.compile(r"""["']([^"'\s]*\.md)["']""", re.I)
MD_TOKEN = re.compile(r"\.md$", re.I)
GLOB = re.compile(r"[*?\[]")


def tokens(command):
    lex = shlex.shlex(command, posix=True, punctuation_chars="();<>|&\n")
    lex.whitespace = " \t\r"
    lex.whitespace_split = True
    return list(lex)


def segments(command):
    current = []
    for token in tokens(command):
        if token in SEPARATORS:
            if current:
                yield current
            current = []
        else:
            current.append(token)
    if current:
        yield current


def md_paths(args):
    found, skip = set(), False
    for arg in args:
        if skip:
            skip = False
            continue
        if arg in (">", ">>"):
            skip = True
            continue
        if arg.startswith("-") or not MD_TOKEN.search(arg):
            continue
        found.update({arg + "#1", arg + "#2"} if GLOB.search(arg) else {arg})
    return found


def inline_code(args):
    for flag in ("-c", "-e", "--eval"):
        if flag in args[:-1]:
            return args[args.index(flag) + 1]
    return None


def shell_code(args):
    """The script of sh -c / bash -lc, or None."""
    for i, arg in enumerate(args[:-1]):
        if re.match(r"^-[a-z]*c$", arg):
            return args[i + 1]
    return None


HEREDOC = re.compile(r"""^([^\n]*?)<<-?[ \t]*(['"]?)(\w+)\2([^\n]*)\n(.*?)\n[ \t]*\3[ \t]*(?=\n|$)""", re.S | re.M)


def code_md(code):
    """Quoted .md literals of inline interpreter code that reads files; globs count as two."""
    found = set()
    if READ_CALL.search(code):
        paths = MD_LITERAL.findall(code)
        try:
            tree = ast.parse(code)
        except SyntaxError:
            pass  # Other interpreters retain the conservative literal fallback.
        else:
            destinations = set()
            parents = {id(child): node for node in ast.walk(tree) for child in ast.iter_child_nodes(node)}

            def write_only(node):
                parent = parents.get(id(node))
                if isinstance(parent, ast.Attribute) and parent.value is node:
                    if parent.attr == "parent":
                        parent = parents.get(id(parent))
                        if not isinstance(parent, ast.Attribute) or parent.attr != "mkdir":
                            return False
                    elif parent.attr not in ("write_text", "write_bytes"):
                        return False
                    return isinstance(parents.get(id(parent)), ast.Call) and parents[id(parent)].func is parent
                if isinstance(parent, ast.Call) and parent.args and parent.args[0] is node:
                    if isinstance(parent.func, ast.Name) and parent.func.id == "open":
                        mode = parent.args[1] if len(parent.args) > 1 else next(
                            (kw.value for kw in parent.keywords if kw.arg == "mode"), None
                        )
                        return isinstance(mode, ast.Constant) and isinstance(mode.value, str) and (
                            any(flag in mode.value for flag in "wax") and "+" not in mode.value
                        )
                return False

            bindings = {}
            for node in ast.walk(tree):
                if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                    receiver = node.value
                    if isinstance(receiver, ast.Call) and (
                        isinstance(receiver.func, ast.Name) and receiver.func.id == "Path"
                        or isinstance(receiver.func, ast.Attribute) and receiver.func.attr == "Path"
                    ):
                        bindings[node.targets[0].id] = receiver
                if not isinstance(node, ast.Call):
                    continue
                receiver = node.func.value if isinstance(node.func, ast.Attribute) else None
                if isinstance(node.func, ast.Attribute) and node.func.attr in ("write_text", "write_bytes"):
                    if isinstance(receiver, ast.Call) and (
                        isinstance(receiver.func, ast.Name) and receiver.func.id == "Path"
                        or isinstance(receiver.func, ast.Attribute) and receiver.func.attr == "Path"
                    ):
                        destinations.update(id(arg) for arg in receiver.args if isinstance(arg, ast.Constant))
                if isinstance(node.func, ast.Name) and node.func.id == "open" and node.args:
                    mode = node.args[1] if len(node.args) > 1 else next(
                        (kw.value for kw in node.keywords if kw.arg == "mode"), None
                    )
                    if isinstance(mode, ast.Constant) and isinstance(mode.value, str):
                        if any(flag in mode.value for flag in "wax") and "+" not in mode.value:
                            # Do not discard nested read calls in a dynamic filename.
                            if isinstance(node.args[0], ast.Constant):
                                destinations.add(id(node.args[0]))
            for name, receiver in bindings.items():
                references = [node for node in ast.walk(tree) if isinstance(node, ast.Name) and node.id == name]
                # One binding, no aliases/unknown consumers and no actual reads.
                # A separate occurrence of the same filename remains counted.
                if sum(isinstance(node.ctx, ast.Store) for node in references) == 1 and any(
                    isinstance(node.ctx, ast.Load) for node in references
                ) and all(isinstance(node.ctx, ast.Store) or write_only(node) for node in references):
                    destinations.update(id(arg) for arg in receiver.args if isinstance(arg, ast.Constant))
            # Remove only the proved write occurrences, not every identical
            # pathname: another occurrence may be a real read. Keep the existing
            # fallback for bytes, escaped literals and non-Python syntax.
            for node in ast.walk(tree):
                if id(node) in destinations and isinstance(node, ast.Constant):
                    if isinstance(node.value, str) and node.value in paths:
                        paths.remove(node.value)
        for path in paths:
            found.update({path + "#1", path + "#2"} if GLOB.search(path) else {path})
    return found


def heredocs(command):
    """The command without heredoc bodies, and the .md paths an interpreter heredoc reads."""
    found = set()

    def strip(match):
        prefix, rest, body = match.group(1), match.group(4), match.group(5)
        words = list(segments(prefix))
        words = words[-1] if words else []
        while words and (words[0] in PREFIXES or re.match(r"^\w+=", words[0])):
            words = words[1:]
        if words and os.path.basename(words[0]) in INTERPRETERS:
            found.update(code_md(body))
        return prefix + rest

    return HEREDOC.sub(strip, command), found


def reads(command, depth=0):
    """Distinct .md paths the command prints; globs count as two."""
    command, found = heredocs(command)
    loop_words, reader_on_variable = set(), False
    for words in segments(command):
        while words and (words[0] in PREFIXES or re.match(r"^\w+=", words[0])):
            words = words[1:]
        if not words:
            continue
        name, args = os.path.basename(words[0]), words[1:]
        if name == "for" and "in" in args:
            loop_words.update(md_paths(args[args.index("in") + 1:]))
        elif name in SHELLS and depth < 3:
            code = shell_code(args)
            if code is not None:
                found |= reads(code, depth + 1)
        elif name in INTERPRETERS:
            code = inline_code(args)
            if code is not None:
                found |= code_md(code)
        elif name in READERS:
            if name == "sed" and any(re.match(r"^-[a-zA-Z]*i", a) or a.startswith("--in-place") for a in args):
                continue
            paths = md_paths(args)
            found |= paths
            if not paths and any("$" in a for a in args):
                reader_on_variable = True
    if reader_on_variable:
        found |= loop_words
    return found


try:
    data = json.loads(os.environ.get("TEA_RAGS_HOOK_INPUT", ""))
    command = (data.get("tool_input") or {}).get("command")
    if isinstance(command, list):
        argv = [str(a) for a in command]
        code = shell_code(argv[1:]) if argv and os.path.basename(argv[0]) in SHELLS else None
        command = code if code is not None else shlex.join(argv)
    if not isinstance(command, str):
        sys.exit(0)
    count = len(reads(command))
except SystemExit:
    raise
except Exception:
    sys.exit(0)

if count >= 2:
    sys.stderr.write(
        "tea-rags: read ONE file per command — this command prints %d .md files and output past "
        "~10k tokens loses its middle. Re-run with one file per command (sed -n ranges for long files; an indexed file → find_symbol(relativePath:) instead).\n" % count
    )
    sys.exit(2)
sys.exit(0)
PY
